// v2 (2026-07-08) — GATE POR TELÉFONO. Reemplaza el criterio v1 ("registra apenas hay
// nombre/email/telefono"). Ahora: sin teléfono numérico válido → REJECTED, no registra nada.
// El teléfono se resuelve por coalesce: primero el determinístico de ManyChat
// (telefono_webhook, viene del main), y como fallback el que el lead escribió en el chat
// (telefono, vía $fromAI). Descarta el placeholder {{phone}} sin resolver.

const args = $input.first().json;
const nombre = String(args.nombre || '').trim();
const email = String(args.email || '').trim().toLowerCase();
const subscriber_id = String(args.subscriber_id || '').trim();

// --- Helpers de teléfono ---
const digitsOf = (s) => String(s || '').replace(/[^\d]/g, '');
const isValidPhone = (s) => {
  const raw = String(s || '').trim();
  if (!raw || raw === '{{phone}}') return false;          // placeholder ManyChat sin resolver
  if (!/^\+?[\d\s().-]+$/.test(raw)) return false;         // solo dígitos + separadores
  return digitsOf(raw).length >= 6;                        // mínimo de dígitos reales
};
const cleanPhone = (s) => {
  const d = digitsOf(s);
  return String(s).trim().startsWith('+') ? ('+' + d) : d;
};

// --- Coalesce: determinístico (ManyChat) → agéntico (chat) ---
const rawWebhook = String(args.telefono_webhook || '').trim();   // determinístico
const rawChat    = String(args.telefono || '').trim();           // lo escribió el lead
let telefono = '';
if (isValidPhone(rawWebhook)) telefono = cleanPhone(rawWebhook);
else if (isValidPhone(rawChat)) telefono = cleanPhone(rawChat);

// subscriber_id requerido para upsert (identifica al lead). Sin él, es bug del main.
if (!subscriber_id) {
  return [{ json: { status: 'ERROR', _skip: true, message_to_agent: 'No se puede registrar/actualizar el lead sin subscriber_id. Debería venir del contexto del agente.' } }];
}

// GATE DURO: sin teléfono numérico válido → REJECTED. No escribe nada, no corta el flujo del agente.
if (!telefono) {
  return [{ json: { status: 'REJECTED', reason: 'telefono_invalido', _skip: true, message_to_agent: 'No registré al lead: todavía no hay un teléfono válido. Si ManyChat no trajo el número (llegó {{phone}}) pedile al lead que lo escriba en el chat, y volvé a invocar la tool cuando lo tengas.' } }];
}

// Validar formato de email SOLO si vino
if (email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return [{ json: { status: 'ERROR', _skip: true, message_to_agent: `El email "${email}" no tiene formato válido. Pedile al cliente que lo confirme y volvé a llamar la tool.` } }];
  }
}

// Normalizar origen
const origenesValidos = ['newsletter', 'derivacion', 'descuento_insumos', 'otro'];
const origen = origenesValidos.includes(String(args.origen || '').toLowerCase())
  ? String(args.origen).toLowerCase()
  : 'otro';

// Normalizar canal
const canal = String(args.canal || '').trim() || 'desconocido';

return [{
  json: {
    timestamp: new Date().toISOString(),
    nombre,
    email,
    telefono,
    canal,
    subscriber_id,
    aplicacion_interes: String(args.aplicacion_interes || '').trim(),
    origen,
    session_id: String(args.session_id || '').trim() || 'unknown'
  }
}];

// v1 — Merge defensivo: existente + nuevo, sin pisar campos previos con vacíos.
// Detecta qué se agregó vs qué ya estaba para el message_to_agent.
const existing = $input.first().json;
const nuevo = $('Validate Input').first().json;

const merge = (a, b) => (b && String(b).trim() !== '') ? b : (a || '');

const merged = {
  timestamp: existing.timestamp || nuevo.timestamp,
  nombre: merge(existing.nombre, nuevo.nombre),
  email: merge(existing.email, nuevo.email),
  telefono: merge(existing.telefono, nuevo.telefono),
  subscriber_id: existing.subscriber_id || nuevo.subscriber_id,
  session_id: merge(existing.session_id, nuevo.session_id),
  canal: merge(existing.canal, nuevo.canal),
  aplicacion_interes: merge(existing.aplicacion_interes, nuevo.aplicacion_interes),
  origen: existing.origen || nuevo.origen
};

// Diff para el message_to_agent
const camposAgregados = [];
const camposActualizados = [];
const camposYaExistentes = [];
['nombre', 'email', 'telefono', 'aplicacion_interes'].forEach(k => {
  const tieneNuevo = nuevo[k] && String(nuevo[k]).trim() !== '';
  const tieneExistente = existing[k] && String(existing[k]).trim() !== '';
  if (tieneNuevo && !tieneExistente) camposAgregados.push(k);
  else if (tieneNuevo && tieneExistente && existing[k] !== nuevo[k]) camposActualizados.push(k);
  else if (tieneExistente) camposYaExistentes.push(k);
});

return [{ json: { ...merged, _agregados: camposAgregados, _actualizados: camposActualizados, _ya_existentes: camposYaExistentes } }];

const v = $('Validate Input').first().json;
const m = $('Merge with existing').first().json;
const agregados = m._agregados || [];
const actualizados = m._actualizados || [];
const yaExistentes = m._ya_existentes || [];

const partes = [];
if (agregados.length) partes.push(`agregados: ${agregados.join(', ')}`);
if (actualizados.length) partes.push(`actualizados: ${actualizados.join(', ')}`);
if (yaExistentes.length) partes.push(`ya estaban: ${yaExistentes.join(', ')}`);
const resumen = partes.length ? ` Datos ${partes.join(' · ')}.` : '';

return [{ json: {
  status: 'RESOLVED',
  data: {
    subscriber_id: v.subscriber_id,
    already_exists: true,
    agregados,
    actualizados,
    ya_existentes: yaExistentes,
    origen: v.origen
  },
  message_to_agent: `Lead ya estaba registrado — fila actualizada en la base.${resumen} Seguí la conversación natural sin re-confirmar los datos ya capturados.`,
  trace_id: $execution.id
} }];

const v = $('Validate Input').first().json;
const camposGuardados = [];
if (v.nombre) camposGuardados.push('nombre');
if (v.email) camposGuardados.push('email');
if (v.telefono) camposGuardados.push('telefono');
return [{ json: {
  status: 'RESOLVED',
  data: {
    subscriber_id: v.subscriber_id,
    already_exists: false,
    timestamp_saved: v.timestamp,
    campos_guardados: camposGuardados,
    origen: v.origen
  },
  message_to_agent: `Lead nuevo registrado en la base con: ${camposGuardados.join(', ')}. Cuando el cliente comparta datos adicionales (email, teléfono u otros), volvé a invocar la tool — la fila se actualiza automáticamente.`,
  trace_id: $execution.id
} }];
